using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
using MedGas2024.Core;
using MedGas2024.UI;
public static class LabelTests
{
    static List<string> log=new List<string>();static string evidence;static void Check(bool value,string text){if(!value)throw new Exception(text);log.Add("PASS: "+text);Console.WriteLine(log.Last());}
    static bool Visible(Control control){var rect=control.RectangleToScreen(control.ClientRectangle);for(var parent=control.Parent;parent!=null;parent=parent.Parent)if(!parent.RectangleToScreen(parent.ClientRectangle).Contains(rect))return false;return true;}
    static bool Reject(Action action){try{action();return false;}catch(ArgumentException){return true;}}
    static IEnumerable<Control> All(Control p){foreach(Control c in p.Controls){yield return c;foreach(var d in All(c))yield return d;}}
    static T Find<T>(Control p,string name)where T:Control{return All(p).OfType<T>().Single(c=>c.Name==name);}
    static void Capture(Form f,string name){Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(evidence,name+".png"));}}
    static LabelCatalog Catalog()
    {
        var c=new LabelCatalog{Fingerprint="snapshot"};c.Members.AddRange(new[]{new LabelMember{Handle="1",Layer="A",Type="U15",Text="D15.Oxy",Color="ACI 3",Scale=.1,NativeHeight=2.5},new LabelMember{Handle="2",Layer="B",Type="Alias15",Text="Oxy.D15",Color="RGB 20,30,40",Scale=.2,NativeHeight=2.5},new LabelMember{Handle="3",Layer="A",Type="Oxy22",Text="D22.Oxy",Color="ACI 1",Scale=.5,NativeHeight=2.5},new LabelMember{Handle="4",Layer="A",Type="HDPE110",Text="D110.HDPE",Color="ACI 201",Scale=1,NativeHeight=2.5},new LabelMember{Handle="5",Layer="LOCKED",Type="U15",Text="D15.Oxy",Color="ACI 7",Scale=.7,Locked=true,NativeHeight=2.5}});
        foreach(var m in c.Members.GroupBy(x=>x.Type).Select(g=>g.First()))c.Definitions.Add(new DrawingLayerInfo{LayerName=m.Type,LinetypeName=m.Type,Text=m.Text,NativeTextHeight=2.5,Height=2.5,Dash=40,Before=12,After=12,Writable=true,Editable=true});return c;
    }
    [STAThread]public static int Main(string[] args)
    {
        evidence=Path.Combine(args[0],"evidence");Application.EnableVisualStyles();try
        {
            var c=Catalog();var exact=c.Groups(false).Single(g=>g.Key==LabelRules.Key("D15.Oxy",false));Check(exact.Lines==3&&exact.Layers==3&&exact.Types==2&&exact.Locked==1,"Exact grouping merges native labels across layers, type aliases and legacy label order");
            Check(c.Groups(true).Single(g=>g.Key==LabelRules.Key("D15.Oxy",true)).Lines==4,"System grouping includes all diameters without merging other systems");Check(c.Groups(false).Count==3&&LabelRules.Key("oxy.D15",false)==LabelRules.Key("D15.Oxy",false),"Grouping is case-insensitive and does not guess from layer suffix RAW");
            Check(new BatchEdit{ChangeText=true,TextTemplate="D{D}.{Label}",ChangeDescription=true,DescriptionTemplate="{System} D{D}"}.NewText(new DrawingLayerInfo{UseLabelIdentity=true,LayerName="Mr.T_OXY_D99_RAW",Text="D15.Oxy"})=="D15.Oxy","Native label identity overrides stale diameter in a type name");Check(LabelRules.Matches("oxy15","D15.Oxy",new[]{"D15.Oxy"})&&LabelRules.Matches("D15Oxy","D15.Oxy",new[]{"D15.Oxy"}),"Compact searches match label characters in both orders");
            var scope=new LabelScope{Keys=new[]{exact.Key},Fingerprint=c.Fingerprint};Check(LabelRules.Select(c,scope).Count==3,"One chosen label expands to all matching member entities");Check(LabelRules.Select(c,new LabelScope{All=true}).Count==5,"Whole-drawing scope includes labels outside the current visible filter");
            var patch=new LabelEdit{ChangeScale=true,Scale=2,Multiply=true};patch.Validate();Check(LabelRules.Scale(.1,patch)==.2&&LabelRules.Scale(.5,patch)==1,"Multiply mode scales each member relative to its own current value");patch.Multiply=false;patch.Scale=.25;Check(LabelRules.Scale(.1,patch)==.25&&LabelRules.Scale(.7,patch)==.25,"Set mode normalizes mixed source scales to the chosen final value");
            Check(Reject(()=>new LabelEdit().Validate())&&Reject(()=>new LabelEdit{ChangeScale=true,Scale=0}.Validate())&&Reject(()=>LabelRules.Scale(1000000,new LabelEdit{ChangeScale=true,Multiply=true,Scale=2})),"Empty actions, zero and overflowing resulting scales are rejected");Check(Reject(()=>new LabelEdit{ForceR=true,Pattern=new BatchEdit{ChangePrefix=true}}.Validate()),"Group edit cannot accidentally mutate shared layer metadata");
            using(var f=new LabelEditForm(c.Members,c.Definitions,n=>201,new ScaleContext(),"TOÀN BỘ NHÃN",true))
            {
                f.Show();Check(Find<CheckBox>(f,"GroupR0").Checked&&!Find<CheckBox>(f,"GroupChangeColor").Checked&&!Find<CheckBox>(f,"GroupChangeScale").Checked,"R0 action explicitly selects rotation while preserving color and scale by default");Find<CheckBox>(f,"GroupChangeColor").Checked=true;Find<Button>(f,"GroupPalette").PerformClick();Find<CheckBox>(f,"GroupChangeScale").Checked=true;Find<ComboBox>(f,"GroupScaleMode").SelectedIndex=1;Find<NumericUpDown>(f,"GroupScale").Value=2;Capture(f,"ui-label-group-edit");f.Size=f.MinimumSize;Capture(f,"ui-label-group-edit-minimum");foreach(string name in new[]{"ReviewLabelGroup","CancelLabelGroup","GroupPaper","GroupPattern"}){var control=Find<Button>(f,name);Check(control.Parent.ClientRectangle.Contains(control.Bounds),name+" remains inside its visible panel");}Find<Button>(f,"ReviewLabelGroup").PerformClick();Check(f.Value.ForceR&&f.Value.Recenter&&f.Value.ChangeColor&&f.Value.Aci==201&&f.Value.ChangeScale&&f.Value.Multiply&&f.Value.Scale==2,"One review captures native R0, color and per-entity scale multiplication together");Check(!f.Value.ChangeWidth&&!f.Value.Pattern.ChangesPattern,"Unselected width and pattern fields remain untouched");
            }
            using(var f=new BatchEditForm(c.Definitions,c.Definitions,null)){f.RestrictToPatterns();f.Show();Check(!Find<CheckBox>(f,"ChangePrefix").Visible&&!Find<CheckBox>(f,"ChangeColor").Visible&&Find<CheckBox>(f,"ChangeFont").Visible,"Advanced pattern editor exposes fonts/text without layer naming or color scope");Find<CheckBox>(f,"ChangeText").Checked=true;Find<TextBox>(f,"BatchText").Text="D{D}.PPR";Find<Button>(f,"ReviewBatch").PerformClick();Check(f.Value.ChangeText&&!f.Value.Renames&&f.Value.TextTemplate=="D{D}.PPR","Advanced patch contains native pattern changes only");}
            int calls=0;LabelScope received=null;LabelEdit value=null;
            using(var f=new LabelManagerForm(c,()=>c,(s,e)=>{calls++;received=s;value=e;return false;},n=>201,new ScaleContext()))
            {
                f.Show();var grid=Find<DataGridView>(f,"LabelGroupsGrid");Check(grid.Rows.Count==3&&!grid.ReadOnly&&grid.Columns["Label"].ReadOnly&&grid.Columns.Cast<DataGridViewColumn>().Count(x=>x is DataGridViewCheckBoxColumn)==1,"Primary manager keeps one row per label and adds one explicit group checkbox column");Capture(f,"ui-label-manager");Find<TextBox>(f,"LabelSearch").Text="Oxy";Check(grid.Rows.Count==2,"Search filters label groups");Find<ComboBox>(f,"LabelGrouping").SelectedIndex=1;Check(grid.Rows.Count==1&&((LabelGroup)grid.Rows[0].DataBoundItem).Lines==4,"System mode clearly expands to every diameter of the chosen system");
                int step=0;bool retained=false;using(var timer=new Timer{Interval=100}){timer.Tick+=delegate{var form=Application.OpenForms.Cast<Form>().OfType<LabelEditForm>().FirstOrDefault();if(form==null)return;if(step++==0){Find<CheckBox>(form,"GroupChangeScale").Checked=true;Find<NumericUpDown>(form,"GroupScale").Value=.3M;Find<Button>(form,"ReviewLabelGroup").PerformClick();}else{retained=Find<NumericUpDown>(form,"GroupScale").Value==.3M;timer.Stop();Find<Button>(form,"CancelLabelGroup").PerformClick();}};timer.Start();Find<Button>(f,"RAllLabels").PerformClick();}
                Check(calls==1&&received.All&&value.ForceR&&value.ChangeScale&&value.Scale==.3,"R0 whole-drawing action covers hidden groups and collects all requested entity changes");Check(retained,"Returning from scope review retains the group options");
                step=0;using(var timer=new Timer{Interval=100}){timer.Tick+=delegate{var form=Application.OpenForms.Cast<Form>().OfType<LabelEditForm>().FirstOrDefault();if(form==null)return;if(step++==0){Find<Button>(form,"ReviewLabelGroup").PerformClick();}else{timer.Stop();Find<Button>(form,"CancelLabelGroup").PerformClick();}};timer.Start();Find<Button>(f,"RLabelGroup").PerformClick();}
                Check(calls==2&&!received.All&&received.SystemMode&&received.Keys.Single()==LabelRules.Key("Oxy",true),"Single group action expands the selected system without choosing each layer");f.Size=f.MinimumSize;Capture(f,"ui-label-manager-minimum");foreach(string name in new[]{"ReloadLabels","PickLabel","EditLabelGroup","RLabelGroup","EditAllLabels","RAllLabels","AdvancedLayers","LabelLibrary"}){var b=Find<Button>(f,name);Check(b.Parent.ClientRectangle.Contains(b.Bounds),name+" fits at minimum primary window size");}foreach(var caption in All(f).OfType<Label>().Where(x=>x.Name.EndsWith("Caption")))Check(Visible(caption),caption.Name+" remains visible inside all ancestors");f.Close();
            }
            using(var f=new LabelManagerForm(new LabelCatalog(),()=>new LabelCatalog(),(s,e)=>false,n=>201,new ScaleContext())){f.Show();Check(!Find<Button>(f,"RAllLabels").Enabled&&!Find<Button>(f,"EditLabelGroup").Enabled,"Empty drawing has plain disabled scope actions without auto-loading template systems");f.Close();}
            using(var f=new LabelReviewForm("3 matching lines; original definitions preserved",new List<LabelChangeView>{new LabelChangeView{Handle="A1",Label="D15.Oxy",Layer="A",Before="Scale=.1, RGB",After="R=0, Scale=.25, ACI 201"}})){f.Show();Check(Find<Button>(f,"ApplyLabelGroup").Enabled,"Concrete review targets entity count rather than selected layer count");Capture(f,"ui-label-review");f.Close();}
            log.Add("RESULT: PASS; standalone grouping, mathematics and WinForms checks only. Native CAD test is separate.");return 0;
        }catch(Exception ex){log.Add("FAIL: "+ex);Console.WriteLine(ex);return 1;}finally{File.WriteAllLines(Path.Combine(evidence,"label-tests.txt"),log);}
    }
}
